# Simple local basemap. Natural Earth data are public domain; extract the 110m land shapefile.
url='https://naturalearth.s3.amazonaws.com/110m_physical/ne_110m_land.zip'
try:
 import io
 raw=urllib.request.urlopen(url,timeout=60).read();z=zipfile.ZipFile(io.BytesIO(raw));b=z.read(next(n for n in z.namelist() if n.endswith('.shp')));offset=100;polygons=[]
 while offset<len(b):
  _,words=struct.unpack_from('>II',b,offset);data=b[offset+8:offset+8+words*2];offset+=8+words*2
  if struct.unpack_from('<I',data)[0]!=5:continue
  parts,points=struct.unpack_from('<II',data,36);starts=list(struct.unpack_from('<'+'I'*parts,data,44))+[points];xy=struct.unpack_from('<'+'d'*(points*2),data,44+parts*4)
  polygons.extend([[[round(xy[2*i],3),round(xy[2*i+1],3)] for i in range(starts[k],starts[k+1])] for k in range(parts)])
 (O/'land.json').write_text(json.dumps(polygons,separators=(',',':')));(R/'assets/licenses/NATURAL-EARTH.txt').write_text('Natural Earth 1:110m land. Public domain. Source: '+url+'\nDownload SHA-256: '+hashlib.sha256(raw).hexdigest()+'\nCoastlines are modern generalized reference geography, not ancient territorial boundaries.\n');print('land polygons',len(polygons))
except Exception as e:print('Basemap download failed:',e);raise
