 id='place:'+e['id'];body=f"{e['ancient']} / {e['modern']}\n{e['lat']}, {e['lon']}\n{e['uncertainty']}";db.execute('INSERT OR REPLACE INTO documents VALUES(?,?,?,?,?,?,?)',(id,module,'place',e['ancient'],body,'',json.dumps(e,ensure_ascii=False)));db.execute('DELETE FROM document_search WHERE id=?',(id,));db.execute('INSERT INTO document_search VALUES(?,?,?)',(id,e['ancient'],body))
